freeze_script:
import hashlib
import json
import pathlib
import subprocess
import tempfile

root = pathlib.Path.cwd()
phase = root/'.planning/phases/06.36-viewset-configuration-cli-and-versioned-json-contract-371'
out = pathlib.Path('/tmp/cv-0636-gap-refresh')
sha = lambda data: hashlib.sha256(data).hexdigest()
files = subprocess.check_output(['git','ls-files','src','tests','docs','noxfile.py','pyproject.toml','CHANGELOG.md'], text=True).splitlines()
hashes = {name: sha((root/name).read_bytes()) for name in files}
previous = json.loads((phase/'evidence/review-refresh-fingerprints.json').read_text())
changes = {name: {'before': previous['files'].get(name), 'after': value} for name,value in hashes.items() if previous['files'].get(name)!=value}
removed = sorted(set(previous['files'])-set(hashes))
aux = subprocess.check_output(['git','ls-files','examples','requirements','scripts/check_dist.py','mkdocs.yml','mkdocs.yaml','package.json','package-lock.json','vitest.config.js','vitest.integration.config.js','README.md','LICENSE','.gitignore'], text=True).splitlines()
groups = {}
for group,names in {'source':[f for f in files if f.startswith('src/')], 'tests':[f for f in files if f.startswith('tests/')], 'docs':[f for f in files if f.startswith('docs/')], 'catalogs':[f for f in files if f.endswith(('.po','.mo'))]}.items():
    groups[group] = {'files':len(names),'sha256':sha('\n'.join(f'{name}\0{hashes[name]}' for name in sorted(names)).encode())}
result = {'product_source_head':subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),'files':hashes,'groups':groups,'previous_count':len(previous['files']),'current_count':len(files),'changes_from_previous':changes,'removed_from_previous':removed,'additional_inputs':{name:sha((root/name).read_bytes()) for name in aux}}
for name in ['installed','dist','primary-schema','docs']:
    result[name+'_directory'] = tempfile.mkdtemp(prefix='cv-0636-gap-'+name+'-')
(out/'frozen.json').write_text(json.dumps(result,indent=2)+'\n')
print(json.dumps({k:v for k,v in result.items() if k not in {'files','additional_inputs'}},indent=2))

